void riskyFunction(int code) {
    if (code == 1) {
        throw std::invalid_argument("Invalid parameter");
    } else if (code == 2) {
        throw std::runtime_error("Runtime problem");
    } else if (code == 3) {
        throw 42;  // Throwing an int
    }
}

int main() {
    for (int i = 1; i <= 3; i++) {
        try {
            riskyFunction(i);
        } catch (const std::invalid_argument& e) {
            std::cout << "Invalid argument: " << e.what() << std::endl;
        } catch (const std::runtime_error& e) {
            std::cout << "Runtime error: " << e.what() << std::endl;
        } catch (int num) {
            std::cout << "Caught int: " << num << std::endl;
        } catch (...) {
            std::cout << "Unknown exception caught" << std::endl;
        }
    }

    return 0;
}

#include <iostream>
#include <fstream>
#include <stdexcept>

class SafeResource {
public:
    SafeResource() {
        std::cout << "Resource acquired" << std::endl;
    }
    ~SafeResource() {
        std::cout << "Resource released (destructor)" << std::endl;
    }
};

void mightThrow() {
    SafeResource res;  // Acquired here
    std::cout << "About to throw..." << std::endl;
    throw std::runtime_error("Oops!");
    // Destructor called automatically during stack unwinding!
}

int main() {
    try {
        mightThrow();
    } catch (const std::exception& e) {
        std::cout << "Caught: " << e.what() << std::endl;
    }

    std::cout << "Resource was safely released!" << std::endl;
    return 0;
}

