#include <iostream>
#include <vector>
#include <map>
#include <fstream>
#include <memory>
#include <limits>
#include "student.h"

class StudentManager {
private:
    std::vector<std::unique_ptr<Student>> students;
    std::map<int, size_t> idIndex;
    const std::string filename = "students.dat";

public:
    void addStudent(std::unique_ptr<Student> s) {
        int id = s->getId();
        if (idIndex.count(id)) {
            throw std::invalid_argument("Student ID already exists!");
        }
        idIndex[id] = students.size();
        students.push_back(std::move(s));
    }

    void displayAll() const {
        if (students.empty()) {
            std::cout << "No students registered." << std::endl;
            return;
        }
        std::cout << "\n=== All Students ===" << std::endl;
        for (const auto& s : students) {
            s->displayInfo();
        }
    }

    void findById(int id) const {
        auto it = idIndex.find(id);
        if (it != idIndex.end()) {
            students[it->second]->displayInfo();
        } else {
            std::cout << "Student not found." << std::endl;
        }
    }

    void saveToFile() const {
        std::ofstream file(filename);
        if (!file) throw std::runtime_error("Cannot open file for writing");
        for (const auto& s : students) {
            file << s->toFileString() << std::endl;
        }
        std::cout << "Data saved to " << filename << std::endl;
    }
};

void showMenu() {
    std::cout << "\n=== Student Management System ===" << std::endl;
    std::cout << "1. Add Undergraduate" << std::endl;
    std::cout << "2. Add Graduate" << std::endl;
    std::cout << "3. Display All" << std::endl;
    std::cout << "4. Find by ID" << std::endl;
    std::cout << "5. Save to File" << std::endl;
    std::cout << "6. Exit" << std::endl;
    std::cout << "Choice: ";
}

int main() {
    StudentManager manager;
    int choice;

    do {
        showMenu();
        std::cin >> choice;
        std::cin.ignore();

        try {
            switch (choice) {
                case 1: {
                    std::string name, major;
                    int id; double gpa;
                    std::cout << "Name: "; std::getline(std::cin, name);
                    std::cout << "ID: "; std::cin >> id;
                    std::cout << "GPA: "; std::cin >> gpa;
                    std::cin.ignore();
                    std::cout << "Major: "; std::getline(std::cin, major);
                    manager.addStudent(std::make_unique<Undergraduate>(name, id, gpa, major));
                    std::cout << "Undergraduate added!" << std::endl;
                    break;
                }
                case 2: {
                    std::string name, thesis;
                    int id; double gpa;
                    std::cout << "Name: "; std::getline(std::cin, name);
                    std::cout << "ID: "; std::cin >> id;
                    std::cout << "GPA: "; std::cin >> gpa;
                    std::cin.ignore();
                    std::cout << "Thesis: "; std::getline(std::cin, thesis);
                    manager.addStudent(std::make_unique<Graduate>(name, id, gpa, thesis));
                    std::cout << "Graduate added!" << std::endl;
                    break;
                }
                case 3:
                    manager.displayAll();
                    break;
                case 4: {
                    int id;
                    std::cout << "Enter ID: "; std::cin >> id;
                    manager.findById(id);
                    break;
                }
                case 5:
                    manager.saveToFile();
                    break;
                case 6:
                    std::cout << "Goodbye!" << std::endl;
                    break;
                default:
                    std::cout << "Invalid choice!" << std::endl;
            }
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
            std::cin.clear();
            std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        }
    } while (choice != 6);

    return 0;
